WITH pop_songs AS (
  SELECT * FROM top_songs WHERE genre = 'Pop'
)
SELECT * FROM pop_songs
ORDER BY weeks_on_chart DESC, track_name;

WITH song_artists AS (
  SELECT DISTINCT artist FROM top_songs
),
perf_artists AS (
  SELECT DISTINCT artist_name FROM festival_performances
)
SELECT s.artist
FROM song_artists s
JOIN perf_artists p ON s.artist = p.artist_name
ORDER BY s.artist;

WITH big_venues AS (
  SELECT * FROM venues WHERE capacity > 3000
)
SELECT * FROM big_venues
ORDER BY capacity DESC, name;

WITH chart_snapshot AS (
  SELECT track_name, weeks_on_chart FROM top_songs
)
SELECT * FROM chart_snapshot
ORDER BY weeks_on_chart DESC, track_name;
